$_GET['refresh']='1';ob_start();include __DIR__.'/garden_feed.php';$raw=ob_get_clean();$data=json_decode($raw,true)?:[];$channels=$data['result']??[];
function check_url($url){if(!filter_var($url,FILTER_VALIDATE_URL)||!function_exists('curl_init'))return false;$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_NOBODY=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>15,CURLOPT_USERAGENT=>'Mozilla/5.0 GardenPlaylist/1.0',CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>false]);curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($code>=200&&$code<400)return true;$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RANGE=>'0-1023',CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>15,CURLOPT_USERAGENT=>'Mozilla/5.0 GardenPlaylist/1.0',CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>false]);curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return $code>=200&&$code<400;}
function write_m3u($file,$channels){$f=fopen($file,'wb');fwrite($f,"#EXTM3U\n");foreach($channels as $c){$n=$c['name']??'Channel';$u=$c['url']??'';$l=$c['logo']??'';$g=$c['cat']??'Entertainment';$lang=$c['lang']??'All';if($u==='')continue;fwrite($f,sprintf("#EXTINF:-1 tvg-logo=\"%s\" group-title=\"%s\" tvg-language=\"%s\",%s\n%s\n",htmlspecialchars($l,ENT_QUOTES),htmlspecialchars($g,ENT_QUOTES),htmlspecialchars($lang,ENT_QUOTES),$n,$u));}fclose($f);}
$working=[];$bad=[];foreach($channels as $i=>$c){$ok=check_url($c['url']??'');if($ok)$working[]=$c;else$bad[]=$c;echo sprintf("[%d/%d] %s => %s\n",$i+1,count($channels),$c['name']??'Channel',$ok?'WORKING':'NON-WORKING');}write_m3u(__DIR__.'/working.m3u',$working);write_m3u(__DIR__.'/non_working.m3u',$bad);file_put_contents(__DIR__.'/status.json',json_encode(['generated_at'=>gmdate('c'),'total'=>count($channels),'working'=>count($working),'non_working'=>count($bad)],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));echo "TOTAL ".count($channels)." | WORKING ".count($working)." | NON-WORKING ".count($bad)."\n";
